# AI Office Startup and Health Utilities Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found at E:\AI\AI-Office" }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
function Write-EmbeddedFile {
 param([string]$RelativePath,[string]$Base64Content)
 $Destination = Join-Path $Repository $RelativePath
 $Parent = Split-Path -Parent $Destination
 if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
 if (Test-Path -LiteralPath $Destination -PathType Leaf) {
   $BackupPath = Join-Path $BackupDirectory $RelativePath
   $BackupParent = Split-Path -Parent $BackupPath
   if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
   Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
 }
 [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\health\health-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\health\Get-AIOfficeGatewayToken.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\health\Get-AIOfficeSystemHealth.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\health\Start-AIOffice.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\health\Test-AIOfficeHealthUtilities.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-Startup-Health-Guide.md" -Base64Content ""
$Scripts = Get-ChildItem -LiteralPath "E:\AI\AI-Office\scripts\health" -Filter "*.ps1" -File
foreach ($Script in $Scripts) {
 $Tokens=$null; $ParseErrors=$null
 [System.Management.Automation.Language.Parser]::ParseFile($Script.FullName,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
 if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $Script.FullName + ": " + (($ParseErrors | ForEach-Object {$_.Message}) -join "; ")) }
}
Get-Content -LiteralPath "E:\AI\AI-Office\config\health\health-policy.json" -Raw | ConvertFrom-Json | Out-Null
Write-Host ""
Write-Host "AI Office Startup and Health Utilities installed successfully." -ForegroundColor Green